    try{media_mkdir($dir);$formats=$source['alpha']?['png','webp']:['jpeg','webp'];if(!function_exists('imagewebp')&&!extension_loaded('imagick'))$formats=array_values(array_diff($formats,['webp']));foreach(MEDIA_IMAGE_WIDTHS as $target){if($target>$source['width'])continue;$height=(int)round($source['height']*$target/$source['width']);foreach($formats as $format){$extension=$format==='jpeg'?'jpg':$format;$relativePath=$base.'/responsive/'.$target.'.'.$extension;$absolute=media_upload_root().'/'.$relativePath;media_write_image($source,$target,$height,$format,$absolute);if(!is_file($absolute)||filesize($absolute)<1)throw new RuntimeException('derivative_write_failed');$db->prepare('INSERT INTO media_derivatives(version_id,derivative_kind,width,height,format,mime_type,path,byte_size,checksum,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$versionId,'responsive',$target,$height,$format,$format==='jpeg'?'image/jpeg':'image/'.$format,$relativePath,filesize($absolute),hash_file('sha256',$absolute),gmdate('c')]);$created[]=$absolute;}}}catch(Throwable $e){foreach($created as $file)@unlink($file);throw $e;}finally{media_release_image($source);}
}
function media_create(PDO $db,array $file,?int $replaceAsset=null):array{
