function media_derivatives(PDO $db,int $versionId):array{$q=$db->prepare('SELECT * FROM media_derivatives WHERE version_id=? ORDER BY width,format');$q->execute([$versionId]);return array_map(fn($row)=>['id'=>(int)$row['id'],'kind'=>$row['derivative_kind'],'width'=>(int)$row['width'],'height'=>(int)$row['height'],'format'=>$row['format'],'mimeType'=>$row['mime_type']??($row['format']==='jpeg'?'image/jpeg':'image/'.$row['format']),'path'=>$row['path'],'sizeBytes'=>(int)$row['byte_size'],'checksum'=>$row['checksum']??'','src'=>media_url($row['path'])],$q->fetchAll());}
function media_version_rows(PDO $db,int $assetId):array{$q=$db->prepare('SELECT * FROM media_versions WHERE asset_id=? ORDER BY id DESC');$q->execute([$assetId]);return array_map(fn($row)=>['id'=>(int)$row['id'],'versionUuid'=>$row['version_uuid'],'mimeType'=>$row['mime_type'],'width'=>$row['width']===null?null:(int)$row['width'],'height'=>$row['height']===null?null:(int)$row['height'],'sizeBytes'=>(int)$row['byte_size'],'checksum'=>$row['checksum'],'status'=>$row['processing_status'],'createdAt'=>$row['created_at'],'url'=>media_url($row['original_path']),'derivatives'=>media_derivatives($db,(int)$row['id'])],$q->fetchAll());}
function media_poster_rows(PDO $db,int $versionId):array{$q=$db->prepare('SELECT p.id,p.poster_uuid,p.timestamp_seconds,p.created_at,v.id variant_id,v.variant_key,v.width,v.height,v.format,v.mime_type,v.path,v.size_bytes,v.checksum FROM media_posters p LEFT JOIN media_poster_variants v ON v.poster_id=p.id WHERE p.video_version_id=? ORDER BY p.id DESC,v.width DESC,v.format ASC');$q->execute([$versionId]);$posters=[];foreach($q->fetchAll() as $row){$id=(int)$row['id'];if(!isset($posters[$id]))$posters[$id]=['id'=>$id,'posterUuid'=>$row['poster_uuid'],'timestamp'=>(float)$row['timestamp_seconds'],'createdAt'=>$row['created_at'],'variants'=>[]];if($row['variant_id']!==null)$posters[$id]['variants'][]=['key'=>$row['variant_key'],'format'=>$row['format'],'mimeType'=>$row['mime_type'],'width'=>(int)$row['width'],'height'=>(int)$row['height'],'path'=>$row['path'],'sizeBytes'=>(int)$row['size_bytes'],'checksum'=>$row['checksum'],'src'=>media_url($row['path'])];}return array_values($posters);}
function media_asset(PDO $db,int $id):array{$q=$db->prepare('SELECT a.*,v.original_path,v.version_uuid,v.processing_status version_processing_status FROM media_assets a LEFT JOIN media_versions v ON v.id=a.active_version_id WHERE a.id=?');$q->execute([$id]);$a=$q->fetch();if(!$a)throw new RuntimeException('asset_not_found');$a['id']=(int)$a['id'];$a['active_version_id']=$a['active_version_id']===null?null:(int)$a['active_version_id'];$a['derivatives']=$a['active_version_id']?media_derivatives($db,$a['active_version_id']):[];$a['versions']=media_version_rows($db,$a['id']);$a['url']=$a['kind']==='video'?media_video_url($a['id'],(int)$a['active_version_id'],(string)$a['original_path']):media_url((string)$a['original_path']);$a['posters']=$a['kind']==='video'?media_poster_rows($db,(int)$a['active_version_id']):[];if($a['posters']){$variants=$a['posters'][0]['variants'];$jpeg=array_values(array_filter($variants,fn($v)=>$v['format']==='jpeg'));$a['poster']=$jpeg[0]??$variants[0]??null;}else $a['poster']=null;return $a;}
function media_list(PDO $db):array{$rows=$db->query('SELECT id FROM media_assets WHERE archived_at IS NULL ORDER BY id DESC')->fetchAll();return array_map(fn($r)=>media_asset($db,(int)$r['id']),$rows);}
function media_image_sources(PDO $db,?int $assetId,?int $versionId,string $fallback):array{if(!$assetId||!$versionId)return ['src'=>$fallback,'srcset'=>''];$q=$db->prepare('SELECT a.kind,v.original_path FROM media_assets a JOIN media_versions v ON v.asset_id=a.id WHERE a.id=? AND v.id=? AND v.processing_status="ready"');$q->execute([$assetId,$versionId]);$row=$q->fetch();if(!$row||$row['kind']!=='image')return ['src'=>$fallback,'srcset'=>''];$derivatives=media_derivatives($db,$versionId);$primary=array_values(array_filter($derivatives,fn($d)=>$d['format']==='jpeg'||$d['format']==='png'));if(!$primary)return ['src'=>media_url($row['original_path']),'srcset'=>''];$src=$primary[count($primary)-1]['src'];return ['src'=>$src,'srcset'=>implode(', ',array_map(fn($d)=>$d['src'].' '.$d['width'].'w',$primary))];}
function media_usage(PDO $db,int $assetId):array{$q=$db->query('SELECT a.admin_name,a.slug,c.draft_json,c.published_json FROM activities a JOIN content_documents c ON c.activity_id=a.id ORDER BY a.id');$uses=[];foreach($q->fetchAll() as $row)foreach(['draft_json'=>'Rascunho','published_json'=>'Publicado'] as $column=>$state){$document=json_decode((string)$row[$column],true);foreach(($document['images']??[]) as $element=>$value)if((int)($value['mediaAssetId']??0)===$assetId)$uses[]=['activity'=>$row['admin_name'],'slug'=>$row['slug'],'state'=>$state,'element'=>$element,'versionId'=>(int)($value['mediaVersionId']??0)];} $asset=media_asset($db,$assetId);foreach($uses as &$use)$use['isActiveVersion']=$use['versionId']===$asset['active_version_id'];unset($use);return $uses;}
function media_poster_source(string $file,string $mime):array{if(extension_loaded('imagick')){$image=new Imagick($file);$image->setImageColorspace(Imagick::COLORSPACE_SRGB);return ['engine'=>'imagick','image'=>$image];}if(!extension_loaded('gd'))throw new RuntimeException('image_engine_unavailable');$image=$mime==='image/jpeg'?@imagecreatefromjpeg($file):@imagecreatefrompng($file);if(!$image)throw new RuntimeException('frame_decode_failed');return ['engine'=>'gd','image'=>$image];}
function media_write_poster_variant(array $source,int $sourceWidth,int $sourceHeight,int $width,int $height,string $format,string $path):void{if($source['engine']==='imagick'){$image=clone $source['image'];$image->resizeImage($width,$height,Imagick::FILTER_LANCZOS,1);$image->setImageFormat($format==='jpeg'?'jpeg':'webp');$image->setImageCompressionQuality(86);$image->writeImage($path);$image->clear();return;}$out=imagecreatetruecolor($width,$height);$background=imagecolorallocate($out,0,0,0);imagefill($out,0,0,$background);imagecopyresampled($out,$source['image'],0,0,0,0,$width,$height,$sourceWidth,$sourceHeight);$ok=$format==='jpeg'?imagejpeg($out,$path,86):(function_exists('imagewebp')&&imagewebp($out,$path,84));imagedestroy($out);if(!$ok)throw new RuntimeException('poster_write_failed');}
function media_create_poster(PDO $db,int $assetId,int $versionId,float $timestamp,array $file):array{if(!is_finite($timestamp)||$timestamp<0)throw new RuntimeException('invalid_timestamp');if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_file((string)($file['tmp_name']??''))||($file['size']??0)<1||($file['size']??0)>MEDIA_POSTER_MAX_BYTES)throw new RuntimeException('invalid_frame');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png'],true))throw new RuntimeException('invalid_frame_type');$info=@getimagesize($file['tmp_name']);if(!$info||$info[0]<1||$info[1]<1)throw new RuntimeException('invalid_frame');$q=$db->prepare('SELECT a.asset_uuid,a.kind,v.id,v.version_uuid FROM media_assets a JOIN media_versions v ON v.asset_id=a.id WHERE a.id=? AND v.id=? AND v.processing_status="ready"');$q->execute([$assetId,$versionId]);$video=$q->fetch();if(!$video||$video['kind']!=='video')throw new RuntimeException('invalid_video_version');$uuid=bin2hex(random_bytes(16));$now=gmdate('c');$dir=media_upload_root().'/'.$video['asset_uuid'].'/'.$video['version_uuid'].'/posters/'.$uuid;$source=null;$db->beginTransaction();try{media_mkdir($dir);$source=media_poster_source($file['tmp_name'],$mime);$db->prepare('INSERT INTO media_posters(video_asset_id,video_version_id,poster_uuid,timestamp_seconds,source_width,source_height,created_at) VALUES(?,?,?,?,?,?,?)')->execute([$assetId,$versionId,$uuid,$timestamp,$info[0],$info[1],$now]);$posterId=(int)$db->lastInsertId();$widths=array_values(array_filter(MEDIA_IMAGE_WIDTHS,fn($width)=>$width<=$info[0]));if(!$widths)$widths=[$info[0]];$variants=[];foreach($widths as $width){$height=(int)round($info[1]*$width/$info[0]);foreach(['jpeg','webp'] as $format){if($format==='webp'&&!function_exists('imagewebp')&&!extension_loaded('imagick'))continue;$fileName=$width.'.'.($format==='jpeg'?'jpg':'webp');$path=$dir.'/'.$fileName;media_write_poster_variant($source,$info[0],$info[1],$width,$hei